{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is low (0.00) or neutral, as models tend to overestimate prices in calm periods.",
    "Correct for lagged overestimation: if true price rises sharply after a forecast peak, reduce subsequent forecasts by 5-10% to avoid overshoot.",
    "Apply mean reversion bias correction: if 3-5 consecutive forecasts are above true price, reduce next forecast by 2-5% to align with historical mean.",
    "Increase forecast sensitivity to recent sentiment spikes: if sentiment > 0.33, model should respond with upward bias, but cap at 10% above prior forecast to avoid volatility overcorrection.",
    "For horizon > 14 days, reduce forecast growth rate by 15-20% if sentiment remains flat or negative, as long-term drift is often underestimated."
  ]
}
